import pyarrow.parquet as pq
import json
from collections import defaultdict

def norm_in(x):
    if isinstance(x, list): x = '\n'.join(x)
    return '\n'.join(l.rstrip() for l in str(x).split('\n')).strip()

def norm_out(o):
    if isinstance(o, list): o = '\n'.join(str(s) for s in o)
    return tuple(l.strip() for l in str(o).split('\n') if l.strip())

def scan(rows, name):
    print(f'=== {name} ===')
    conflicts = []
    for i, r in enumerate(rows):
        pid = r['extra_info']['problem_id']
        g = json.loads(r['reward_model']['ground_truth'])
        seen = {}
        for j, (a, b) in enumerate(zip(g['inputs'], g['outputs'])):
            k = norm_in(a)
            if k in seen and seen[k][0] != norm_out(b):
                conflicts.append((i, pid, j, seen[k][1], norm_out(b)))
            if k not in seen or len(seen[k][1]) == 0:
                seen[k] = (norm_out(b), j)
    print('semantically-conflicting duplicate inputs:', len(conflicts))
    for c in conflicts[:15]:
        print('  row', c[0], c[1], 'case', c[2], 'vs', c[3], '::', c[4])
    return conflicts

t = pq.read_table('taco_verl/train.parquet').to_pylist()
v = pq.read_table('taco_verl/test.parquet').to_pylist()
ct = scan(t, 'TRAIN')
cv = scan(v, 'TEST')
