"""Analyze every KEPT row whose probe verdict was partial/none:
did some candidate produce outputs that are whitespace/format variants of the
labels (=> label corrupted), or did all candidates produce different values
(=> model never solved it, label probably fine)?
"""
import collections
import glob
import json
import re

import pandas as pd

WS = "/workspace"
fc = json.load(open("/tmp/analyze/final_class.json"))
p3 = {int(k): v for k, v in json.load(open("/tmp/analyze/probe_results.json")).items()}
p4 = {int(k): v for k, v in json.load(open("/tmp/analyze/probe2_results.json")).items()}
keep = set(fc["keep"]) | {937}
cls = fc["cls"]

tr = pd.read_parquet(f"{WS}/taco_verl/train.parquet")


def qtext(content):
    s = content.split("QUESTION:", 1)[1] if "QUESTION:" in content else content
    s = s.split("ANSWER:")[0]
    return re.sub(r"\s+", " ", s).strip()


idx = {qtext(r["prompt"][0]["content"]): i for i, r in tr.iterrows()}
per_row = collections.defaultdict(list)
for f in sorted(glob.glob(f"{WS}/rollout_data/*.jsonl")):
    for line in open(f):
        d = json.loads(line)
        i = idx.get(qtext(d["input"]))
        if i is not None:
            per_row[i].append((float(d.get("pass_rate", d["score"])), d["output"]))


def as_text(x):
    return x if isinstance(x, str) else "\n".join(str(y) for y in x)


def tokens(o):
    return tuple(str(o).split())


susp = []
for i in sorted(keep):
    v3, v4 = p3.get(i, {}).get("verdict"), p4.get(i, {}).get("verdict")
    if (v4 or v3) in ("partial", "none", "hard_timeout"):
        susp.append(i)
print(f"kept rows with partial/none/timeout verdict: {len(susp)}")

report = []
for i in susp:
    r = tr.iloc[i]
    g = json.loads(r["reward_model"]["ground_truth"])
    n = len(g["outputs"])
    lab_toks = collections.Counter(tokens(o) for o in g["outputs"])
    # best candidate: highest dump pass_rate
    cands = sorted(per_row.get(i, []), key=lambda x: -x[0])
    best_pr, best_text = (cands[0] if cands else (None, None))
    info = {"row": i, "pid": r["extra_info"]["problem_id"], "cls": cls.get(str(i)),
            "n": n, "verdict": (p3.get(i, {}).get("verdict"), p4.get(i, {}).get("verdict")),
            "n_rollouts": len(per_row.get(i, [])), "best_dump_pr": best_pr,
            "fmt_inconsist": None}
    report.append(info)

# join with the format-inconsistency result
def fmt_inconsistency(row):
    g = json.loads(row["reward_model"]["ground_truth"])
    by_tok = collections.defaultdict(set)
    for o in g["outputs"]:
        t = tokens(o)
        if len(t) > 1:
            by_tok[t].add("lines" if "\n" in str(o).strip() else "joined")
    return sum(1 for f in by_tok.values() if len(f) > 1)

for info in report:
    info["fmt_inconsist"] = fmt_inconsistency(tr.iloc[info["row"]])

c = collections.Counter((x["cls"], x["verdict"][1] or x["verdict"][0]) for x in report)
print("by (class, final verdict):", dict(c))
fi = [x for x in report if x["fmt_inconsist"]]
print(f"\nof these, format-inconsistent (mangling signature): {len(fi)}")
for x in fi:
    print("   ", x)
print(f"\nverdict=partial (some candidate outputs matched labels in place) and NOT fmt-inconsistent:")
for x in report:
    if (x["verdict"][1] or x["verdict"][0]) == "partial" and not x["fmt_inconsist"]:
        print(f"    row {x['row']:4d} {x['pid']:14s} cls={x['cls']:22s} n={x['n']:3d} "
              f"rollouts={x['n_rollouts']} best_dump_pr={x['best_dump_pr']}")
json.dump(report, open("/tmp/analyze2/susp_analysis.json", "w"), default=str)

