"""Extra solver-free corruption signals for train.parquet.

1. duplicate-input consistency: if the same test input appears twice in a row, the
   stored outputs must be identical. A permutation of outputs breaks that.
2. size correlation: for clean rows len(output) usually tracks len(input) across the
   row's cases; a random permutation destroys that correlation.
"""
import collections
import json
import math

import pandas as pd

WS = "/user/user1/autorlbench-runs/20261119204804-38214-2a94/workspace"


def as_text(inp):
    if isinstance(inp, str):
        return inp
    if isinstance(inp, list):
        return "\n".join(str(x) for x in inp)
    return str(inp)


def norm_str(s):
    if not isinstance(s, str):
        s = str(s)
    lines = [ln.strip() for ln in s.replace("\r\n", "\n").split("\n")]
    return "\n".join([ln for ln in lines if ln != ""])


def rank(v):
    order = sorted(range(len(v)), key=lambda i: v[i])
    r = [0.0] * len(v)
    i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and v[order[j + 1]] == v[order[i]]:
            j += 1
        avg = (i + j) / 2.0 + 1
        for k in range(i, j + 1):
            r[order[k]] = avg
        i = j + 1
    return r


def spearman(a, b):
    if len(a) < 3:
        return None
    ra, rb = rank(a), rank(b)
    ma, mb = sum(ra) / len(ra), sum(rb) / len(rb)
    num = sum((x - ma) * (y - mb) for x, y in zip(ra, rb))
    da = math.sqrt(sum((x - ma) ** 2 for x in ra))
    db = math.sqrt(sum((y - mb) ** 2 for y in rb))
    if da == 0 or db == 0:
        return None
    return num / (da * db)


def main():
    tr = pd.read_parquet(f"{WS}/taco_verl/train.parquet")
    dup_broken, dup_ok, rows_with_dup = [], [], []
    rho = {}
    for i, r in tr.iterrows():
        g = json.loads(r["reward_model"]["ground_truth"])
        inputs = [as_text(x) for x in g["inputs"]]
        outs = [norm_str(o) for o in g["outputs"]]
        byin = collections.defaultdict(set)
        for a, b in zip(inputs, outs):
            byin[a].add(b)
        if any(k for k, v in collections.Counter(inputs).items() if v > 1):
            rows_with_dup.append(i)
            if any(len(v) > 1 for v in byin.values()):
                dup_broken.append(i)
            else:
                dup_ok.append(i)
        li = [len(x) for x in inputs]
        lo = [len(x) for x in outs]
        if len(set(li)) > 2 and len(set(lo)) > 2:
            rho[i] = spearman(li, lo)
    print("rows with duplicate inputs:", len(rows_with_dup))
    print("  -> proven BROKEN (same input, different stored output):", len(dup_broken), dup_broken[:30])
    print("  -> consistent:", len(dup_ok))
    print("rows with a computable size-rho:", len(rho))
    vals = [v for v in rho.values() if v is not None]
    vals.sort()
    if vals:
        q = lambda p: vals[int(p * (len(vals) - 1))]
        print(f"rho quantiles: p5={q(.05):.2f} p25={q(.25):.2f} p50={q(.5):.2f} p75={q(.75):.2f} p95={q(.95):.2f}")
    json.dump({"dup_broken": dup_broken, "dup_ok": dup_ok,
               "rho": {str(k): v for k, v in rho.items()}},
              open("/tmp/analyze/extra_signals.json", "w"))


if __name__ == "__main__":
    main()

"""Parallel label probe v3: classify train rows via frozen rollout candidates.

Child processes write one JSON result file per row (no Queue/os._exit race) and the
parent reaps with non-blocking exitcode polling plus a hard kill deadline.
"""
import collections
import glob
import json
import multiprocessing as mp
import os
import re
import shutil
import signal
import sys
import time
from io import StringIO
from unittest.mock import mock_open, patch

import pandas as pd

WS = "/user/user1/autorlbench-runs/20261119204804-38214-2a94/workspace"
OUTDIR = "/tmp/analyze/results"
CASE_TIMEOUT = 2
ROW_DEADLINE = 100
MAX_CANDS = 4
CONCURRENCY = 64


def post_process(text):
    if "```" in text:
        blocks = re.findall(r"```(.*?)```", text, re.DOTALL)
        if len(blocks) == 0:
            text = text.split("```")[1]
        else:
            text = blocks[0]
            if not text.startswith("\n"):
                text = text[max(text.find("\n") + 1, 0):]
    return text


def as_text(inp):
    if isinstance(inp, str):
        return inp
    if isinstance(inp, list):
        return "\n".join(str(x) for x in inp)
    return str(inp)


class TO(Exception):
    pass


def _handler(signum, frame):
    raise TO()


def run_stdin(code, inp):
    ns = {"__name__": "__main__"}
    buf = StringIO()
    lines = iter(inp.split("\n"))
    old_out, old_in = sys.stdout, sys.stdin
    sys.stdout = buf
    signal.alarm(CASE_TIMEOUT)
    try:
        with patch("builtins.open", mock_open(read_data=inp)), \
             patch("sys.stdin", StringIO(inp)), \
             patch("sys.stdin.readline", lambda *a: next(lines)), \
             patch("sys.stdin.readlines", lambda *a: inp.split("\n")), \
             patch("sys.stdin.read", lambda *a: inp):
            exec(compile(code, "<cand>", "exec"), ns)
        return buf.getvalue(), None
    except TO:
        return None, "timeout"
    except SystemExit:
        return buf.getvalue(), None
    except BaseException as e:  # noqa: BLE001
        return None, type(e).__name__
    finally:
        signal.alarm(0)
        sys.stdout, sys.stdin = old_out, old_in


def norm_str(s):
    if not isinstance(s, str):
        s = str(s)
    lines = [ln.strip() for ln in s.replace("\r\n", "\n").split("\n")]
    return "\n".join([ln for ln in lines if ln != ""])


def load_dumps():
    def norm_q(s):
        s = s.split("QUESTION:", 1)[1] if "QUESTION:" in s else s
        s = s.split("ANSWER:")[0]
        return re.sub(r"\s+", " ", s).strip()

    tr = pd.read_parquet(os.path.join(WS, "taco_verl/train.parquet"))
    idx = {}
    for i, r in tr.iterrows():
        idx[norm_q(r["prompt"][0]["content"])] = i
    per_row = collections.defaultdict(list)
    for f in sorted(glob.glob(os.path.join(WS, "rollout_data/*.jsonl"))):
        for line in open(f):
            d = json.loads(line)
            i = idx.get(norm_q(d["input"]))
            if i is None:
                continue
            per_row[i].append((float(d.get("pass_rate", d["score"])), float(d["score"]), d["output"]))
    return tr, per_row


def probe_row(rec):
    signal.signal(signal.SIGALRM, _handler)
    inputs = [as_text(x) for x in rec["inputs"]]
    labels = [norm_str(o) for o in rec["outputs"]]
    label_ms = collections.Counter(labels)
    seen, picked = set(), []
    for pr, sc, text in sorted(rec["cands"], key=lambda x: -x[0]):
        code = post_process(text).strip()
        if code in seen:
            continue
        seen.add(code)
        picked.append((pr, sc, code))
        if len(picked) >= MAX_CANDS:
            break

    out = {"verdict": "none", "cands": [], "n": len(labels), "perm": None}
    for pr, sc, code in picked:
        outs, errs = [], 0
        for inp in inputs:
            o, e = run_stdin(code, inp)
            if e is not None:
                errs += 1
                outs.append(None)
            else:
                outs.append(norm_str(o))
        n_exact = sum(1 for a, b in zip(outs, labels) if a is not None and a == b)
        got = [o for o in outs if o is not None]
        perm = None
        if errs == 0 and n_exact < len(labels) and collections.Counter(got) == label_ms:
            avail = collections.defaultdict(list)
            for j, l in enumerate(labels):
                avail[l].append(j)
            mapping, ok = [], True
            for o in outs:
                slots = avail.get(o)
                if not slots:
                    ok = False
                    break
                mapping.append(slots.pop(0))
            if ok and sorted(mapping) == list(range(len(labels))):
                perm = mapping
        out["cands"].append({"pass_rate": pr, "logged_score": sc, "n_exact": n_exact,
                             "errs": errs, "perm": perm})
        if perm is not None:
            out["verdict"] = "perm"
            out["perm"] = perm
            return out
        if n_exact == len(labels):
            out["verdict"] = "exact"
            return out
        if n_exact > 0 and out["verdict"] == "none":
            out["verdict"] = "partial"
    return out


def _child(i, rec):
    path = os.path.join(OUTDIR, f"{i}.json")
    try:
        res = probe_row(rec)
    except BaseException as e:  # noqa: BLE001
        res = {"verdict": "error", "err": repr(e)}
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(res, f)
    os.replace(tmp, path)
    os._exit(0)


def main():
    if os.path.isdir(OUTDIR):
        shutil.rmtree(OUTDIR)
    os.makedirs(OUTDIR)
    tr, per_row = load_dumps()
    todo = []
    for i, cands in sorted(per_row.items()):
        g = json.loads(tr.iloc[i]["reward_model"]["ground_truth"])
        todo.append((i, {"inputs": list(g["inputs"]), "outputs": list(g["outputs"]), "cands": cands}))
    print(f"rows to probe: {len(todo)}", flush=True)

    ctx = mp.get_context("fork")
    running, k, t0, last = {}, 0, time.time(), 0
    while k < len(todo) or running:
        while len(running) < CONCURRENCY and k < len(todo):
            i, rec = todo[k]
            p = ctx.Process(target=_child, args=(i, rec), daemon=True)
            p.start()
            running[i] = (p, time.time())
            k += 1
        time.sleep(0.05)
        for i in list(running):
            p, started = running[i]
            if p.exitcode is not None:
                running.pop(i)
            elif time.time() - started > ROW_DEADLINE:
                p.kill()
                running.pop(i)
                json.dump({"verdict": "hard_timeout"}, open(os.path.join(OUTDIR, f"{i}.json"), "w"))
        if time.time() - last > 20:
            last = time.time()
            n = len(glob.glob(os.path.join(OUTDIR, "*.json")))
            print(f"  {n}/{len(todo)} done, {len(running)} running, {time.time()-t0:.0f}s", flush=True)

    results = {}
    for f in glob.glob(os.path.join(OUTDIR, "*.json")):
        results[int(os.path.basename(f)[:-5])] = json.load(open(f))
    c = collections.Counter(v["verdict"] for v in results.values())
    print("FINAL", dict(c), "elapsed", f"{time.time()-t0:.0f}s", flush=True)
    json.dump({str(k2): v for k2, v in results.items()}, open("/tmp/analyze/probe_results.json", "w"))
    for verdict in ("perm", "partial", "none", "hard_timeout", "error", "empty"):
        rows = sorted([i for i, v in results.items() if v["verdict"] == verdict])
        print(f"{verdict}: {len(rows)} {rows[:30]}", flush=True)


if __name__ == "__main__":
    main()

